import React from "react";
import { Box, Chip, Typography } from "@mui/material";
import ReportProblemOutlinedIcon from "@mui/icons-material/ReportProblemOutlined";
import LightbulbOutlinedIcon from "@mui/icons-material/LightbulbOutlined";

// The tone is shown as an icon and a word, never by colour alone.
const TONES = {
  warning: { label: "Check", color: "warning", icon: <ReportProblemOutlinedIcon /> },
  insight: { label: "Insight", color: "primary", icon: <LightbulbOutlinedIcon /> },
};

/** Plain-English findings generated by the analytics layer (see analytics.key_findings). */
export default function FindingsList({ findings = [] }) {
  if (!findings.length) {
    return <Typography color="text.secondary">No findings for this dataset.</Typography>;
  }
  return (
    <Box
      component="ul"
      sx={{
        listStyle: "none", m: 0, p: 0, display: "grid", columnGap: 4,
        gridTemplateColumns: { xs: "1fr", md: "repeat(2, 1fr)", xl: "repeat(3, 1fr)" },
      }}
    >
      {findings.map((f) => {
        const tone = TONES[f.tone] || TONES.insight;
        return (
          <Box
            component="li"
            key={f.id || f.title}
            sx={{ display: "grid", gridTemplateColumns: "auto 1fr", gap: 1.5, py: 1.5, borderTop: 1, borderColor: "divider" }}
          >
            <Chip size="small" variant="outlined" color={tone.color} icon={tone.icon} label={tone.label} sx={{ mt: 0.25 }} />
            <Box>
              <Typography sx={{ fontWeight: 600, lineHeight: 1.4 }}>{f.title}</Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mt: 0.25 }}>{f.detail}</Typography>
            </Box>
          </Box>
        );
      })}
    </Box>
  );
}
